function retargetDose(e,doses,modal,animalStatus,date){if(!e||modal.edit)return {...modal,animalStatus,date};const preview=[...doses,{encounterId:e.id,day:modal.day,date,animalStatus}];const days=protocolOf({...e,animalStatus},preview).days;const given=new Set(linkedDoses(e,doses).map(d=>d.day));const next=days.find(([d])=>!given.has(d));const day=next?next[0]:modal.day;return {...modal,animalStatus,date,day,dose:day===modal.day?modal.dose:idShot(e)}}
