const blankBite=()=>({animal:'',animalOther:'',biteType:'',pet:null,vaccinated:null,stray:null,owned:null,owner:'',biteDate:'',biteTime:'',side:'',site:'',place:'',washed:null,tandok:null,wound:[],category:'',rig:'',pepEligible:false,animalStatus:''})
const historyKeys=['iddm','kidney','dialysis','cancer','allergy','steroids','insulin']
const blankHistory=()=>({iddm:null,kidney:null,dialysis:null,cancer:null,allergy:null,steroids:null,insulin:null,others:''})
const openHistory=h=>{
  const src=h||{}
  const untouched=historyKeys.every(k=>src[k]!==true)&&!src.others
  if(untouched) return blankHistory()
  return {others:src.others||'',...Object.fromEntries(historyKeys.map(k=>[k,src[k]===true?true:src[k]===false?false:null]))}
}
const openRerForm=enc=>{
  if(!enc) return enc
  const history=openHistory(enc.history)
  if(enc.rer) return {...enc,history}
  return {...enc,history,vaccine:'',brand:'',regimen:'',rig:'',pepEligible:false}
}
