export function consume(inventory,item,branch,uses=1,batch){const pool=inventory.filter(x=>x.item===item&&x.branch===branch&&x.expiry>=today&&x.stock>0);const line=batch?pool.find(x=>x.batch===batch):pool.slice().sort((a,b)=>a.expiry.localeCompare(b.expiry))[0];if(!line)return {error:'No usable '+item+' stock at '+branch};const capacity=line.usesPerVial||0,total=capacity?(line.uses||0)+uses:1,vials=capacity?Math.floor(total/capacity):1,rest=capacity?total%capacity:0;if(vials>line.stock)return {error:'Insufficient '+item+' stock at '+branch};return {line,vials,rest,inventory:inventory.map(x=>x.id===line.id?{...x,uses:rest,used:x.used+vials,stock:x.stock-vials}:x)}}
