function PatientFields({form,setForm,lockPhilhealth=false,reclassifyOnPhilhealth=false}){const set=(k,v)=>setForm({...form,[k]:v});return <><div className="form-section-title">Patient information (ARC admission form)</div><div className="form-grid"><Field label="Last name" value={form.last} onChange={e=>set('last',e.target.value)} required/><Field label="First name" value={form.first} onChange={e=>set('first',e.target.value)} required/><Field label="Middle name" value={form.middle} onChange={e=>set('middle',e.target.value)} help="Optional. Mother’s maiden surname."/><Field label="Suffix" value={form.suffix} options={suffixes} onChange={e=>set('suffix',e.target.value)} help="Leave blank if none."/><Field label="Cellphone No." value={form.contact} onChange={e=>set('contact',e.target.value)} required help="Required for follow-up contact."/><Field label="Birthday" type="date" value={form.birthday} onChange={e=>setForm({...form,birthday:e.target.value,senior:e.target.value?ageFrom(e.target.value)>=60:false})} required/><Field label="Age" value={form.birthday?ageFrom(form.birthday):''} disabled help="Computed from birthday"/><Field label="Gender" options={['Female','Male']} value={form.sex} onChange={e=>set('sex',e.target.value)} required/><Field label="Branch" options={branches.slice(1)} value={form.branch} onChange={e=>set('branch',e.target.value)}/><Field label="Address" value={form.address} onChange={e=>set('address',e.target.value)} placeholder="House no., barangay, municipality"/><Field label="Municipality / City (DOH report)" options={municipalities.map(m=>m[0]).concat('Others')} value={form.municipality} onChange={e=>setForm({...form,municipality:e.target.value,municipalityOther:e.target.value==='Others'?form.municipalityOther||'':''})} help="DOH catchment list. Choose Others if the patient lives outside these municipalities."/>{form.municipality==='Others'&&<Field label="Specify municipality / city" value={form.municipalityOther||''} onChange={e=>set('municipalityOther',e.target.value)} required placeholder="e.g. San Jose City"/>}</div><Field label="Name of Mother / Father / Guardian" value={form.guardian} onChange={e=>set('guardian',e.target.value)} help="Optional. A minor may sign consent if they can write their name."/><div className="form-section-title">Patient flags</div><div className="check-grid four">{[['Senior','senior'],['PWD','pwd'],['Vetmed','vetmed'],['PhilHealth','philhealth']].map(([l,k])=>{const seniorOn=!!(form.birthday&&ageFrom(form.birthday)>=60);const lock=k==='senior'||(k==='philhealth'&&lockPhilhealth);const checked=k==='senior'?seniorOn:(k==='philhealth'&&lockPhilhealth?false:form[k]);return <Toggle key={k} label={l} checked={checked} disabled={lock} onChange={v=>!lock&&set(k,v)}/>})}</div><p className="card-note">Senior is automatic from birthday (age 60+). PWD, Vetmed and PhilHealth stay manual.</p>{reclassifyOnPhilhealth&&<p className="card-note">Tick <b>PhilHealth</b> to reclassify the current Walk-in visit: ₱0 bill. If already paid, a refund is requested until scheduled Day 7. At a non-accredited branch this becomes For PhilHealth (Day 0 here, then refer).</p>}{lockPhilhealth&&<p className="card-note">PhilHealth is off while <b>Pay now</b> is selected. Choose <b>For PhilHealth</b> if the patient is a member: no payment, give Day 0, then refer.</p>}</>}

