function EncounterPicker({encounters,patients,value,onChange,filter=()=>true,label='Admission / registry'}){const list=encounters.filter(e=>!e.past&&filter(e)).sort((a,b)=>b.registry.localeCompare(a.registry));return <div className="encounter-picker"><label className="field"><span>{label}</span><select value={value||''} onChange={e=>onChange(e.target.value)}><option value="">Select admission</option>{list.map(e=><option key={e.id} value={e.id}>{e.registry} · {(patients.find(p=>p.id===e.patientId)||{}).name}{e.rer?'':' · awaiting RER'}</option>)}</select></label></div>}

