function ScheduleCalendar({rows,focusDate,onPick,onOpen,showBranch}){
  const [month,setMonth]=React.useState(()=>(focusDate||today).slice(0,7))
  React.useEffect(()=>{if(focusDate)setMonth(focusDate.slice(0,7))},[focusDate])
  const [y,m]=month.split('-').map(Number)
  const firstDow=new Date(Date.UTC(y,m-1,1)).getUTCDay()
  const count=new Date(Date.UTC(y,m,0)).getUTCDate()
  const label=new Date(Date.UTC(y,m-1,1)).toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'})
  const shift=n=>{const d=new Date(Date.UTC(y,m-1+n,1));setMonth(d.toISOString().slice(0,7))}
  const cells=[]
  for(let i=0;i<firstDow;i++)cells.push(<div key={'b'+i} className="cal-empty"/>)
  for(let day=1;day<=count;day++){
    const iso=`${y}-${String(m).padStart(2,'0')}-${String(day).padStart(2,'0')}`
    const items=rows.filter(x=>x.date===iso)
    const cls=[iso===today?'today':'',iso===focusDate?'picked':''].filter(Boolean).join(' ')
    cells.push(<div key={iso} className={cls} onClick={()=>onPick(iso===focusDate?'':iso)}><strong>{day}</strong>{items.map(x=><button key={x.id} type="button" className={'cal-apt '+(x.status==='Missed'?'missed':x.status==='Due today'?'due':'')} title={`${x.patient} · ${dayLabel[x.day]} · ${x.status}${x.contact?' · '+x.contact:''}`} onClick={e=>{e.stopPropagation();onOpen(x)}}>{(showBranch?x.branch+' · ':'')+x.patient+' · '+dayLabel[x.day]}</button>)}</div>)
  }
  return <div className="calendar-wrap"><div className="calendar-nav"><button type="button" onClick={()=>shift(-1)} aria-label="Previous month">‹</button><strong>{label}</strong><button type="button" onClick={()=>shift(1)} aria-label="Next month">›</button><button type="button" className="cal-today" onClick={()=>{setMonth(today.slice(0,7));onPick('')}}>Today</button></div><div className="calendar-weekdays">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=><span key={d}>{d}</span>)}</div><div className="calendar-grid">{cells}</div><p className="card-note">Each name is the next dose for that visit. Click the name to record it. Click a day to filter the list.</p></div>
}
export function SchedulePage({branch,notify,schedule,go,setEncounterId,focus,encounters,doses}){const [view,setView]=React.useState('List'),[status,setStatus]=React.useState(focus==='due-today'?'Due today':''),[date,setDate]=React.useState(''),[q,setQ]=React.useState('');React.useEffect(()=>{setStatus(focus==='due-today'?'Due today':'')},[focus]);const rows=schedule.filter(s=>inB(branch,s.branch));const match=x=>(!status||x.status===status)&&(!q||[x.patient,x.registry,x.contact].join(' ').toLowerCase().includes(q.toLowerCase()));const filtered=rows.filter(x=>match(x)&&(!date||x.date===date));const calRows=rows.filter(match);return <><SectionTitle eyebrow="PATIENT MANAGEMENT" title="Follow-up schedule" description="A late dose reschedules the remaining visits from the actual date given. After 7 days past the missed due date the case is Incomplete, but it is not locked — record the dose when the patient returns." action={<div className="segmented"><button className={view==='List'?'active':''} onClick={()=>setView('List')}>List</button><button className={view==='Calendar'?'active':''} onClick={()=>setView('Calendar')}>Calendar</button></div>}/><div className="summary-strip"><div><strong>{rows.filter(x=>x.status==='Due today').length}</strong><span>Due today</span></div><div><strong>{rows.filter(x=>x.status==='Upcoming'&&x.date<=addDays(today,7)).length}</strong><span>Upcoming (7 days)</span></div><div><strong>{rows.filter(x=>x.status==='Missed').length}</strong><span>Missed</span></div></div><div className="notice-line"><Bell size={18}/><span>Due, upcoming, and missed follow-ups show here and in the bell. No SMS. Staff contacts the patient from their own phone using the listed number.</span></div><Card><div className="toolbar"><SearchBox value={q} onChange={setQ} placeholder="Search patient, registry no. or contact..."/><Select value={status} onChange={setStatus} options={['Due today','Upcoming','Missed']} allLabel="All statuses"/><input className="date-filter" type="date" value={date} onChange={e=>setDate(e.target.value)}/></div>{view==='List'?<Table columns={[{label:'PATIENT',render:r=><div><strong>{r.patient}</strong><small className="block-sub">{r.registry}</small></div>},{label:'DOSE',render:r=>dayLabel[r.day]},{label:'VACCINE',key:'vaccine'},{label:'SCHEDULED DATE',render:r=>fmt(r.date)},{label:'BRANCH',key:'branch'},{label:'CELLPHONE',key:'contact'},{label:'STATUS',render:r=><Badge>{r.status}</Badge>},{label:'ACTION',render:r=><div className="row-actions"><button onClick={()=>{setEncounterId(r.encounterId);go('treatments',r.encounterId)}}>{r.status==='Missed'?'Record late dose':'Record dose'}</button></div>}]} rows={filtered}/>:<ScheduleCalendar rows={calRows} focusDate={date} showBranch={branch==='All branches'} onPick={setDate} onOpen={r=>{setEncounterId(r.encounterId);go('treatments',r.encounterId)}}/>}</Card></>}
